var n={name:`Prkno`,description:`Statické držení těla ve vzporu na předloktích. Posiluje svaly trupu a stabilitu středu těla.`,steps:[`Zaujměte vzpor na předloktích, lokty pod rameny.`,`Natáhněte nohy a vyrovnejte tělo od pat po hlavu.`,`Zatněte břišní svaly a hýždě.`,`Vydržte v poloze stanovený čas a dýchejte rovnoměrně.`],warnings:[`Pokud se objeví bolest v ramenou nebo bedrech, cvik přerušte.`],techniqueNotes:[`Pánev nezvedejte ani nespouštějte.`,`Nezadržujte dech.`]};var a={name:`Superman`,description:`Současné zvedání paží a nohou vleže na břiše. Posiluje svaly zad a hýždě.`,steps:[`Lehněte si na břicho, paže natáhněte dopředu.`,`Současně mírně zvedněte paže, hrudník a nohy nad podlahu.`,`Vydržte 1–2 vteřiny.`,`Pomalu se spusťte.`],warnings:[`Nezvedejte se prudce a příliš vysoko.`,`Pokud se objeví bolest v bederní oblasti, cvik přerušte.`],techniqueNotes:[`Pohled dolů, krk v jedné linii se zády.`,`Pohybujte se plynule, bez škubání.`]};var t={name:`Burpee`,description:`Komplexní cvik: dřep, vzpor ležmo, návrat a výskok. Rozvíjí celkovou vytrvalost a zatěžuje celé tělo.`,steps:[`Podřepněte a položte dlaně na podlahu.`,`Odkopněte nohy dozadu do vzporu ležmo.`,`Přitáhněte nohy k rukám a vzpřimte se.`,`Udělejte malý výskok s pažemi nad hlavou.`],warnings:[`Dopadejte měkce a ve vzporu ležmo neprohýbejte bedra.`,`Pokud se objeví bolest v kloubech nebo zádech, cvik přerušte.`],techniqueNotes:[`Ve vzporu držte tělo rovně.`,`Zachovejte kontrolu, nesnažte se o maximální rychlost.`]};var s={"bodyweight-squat":{name:`Dřep s vlastní vahou`,description:`Základní dřep bez zátěže. Posiluje čtyřhlavý sval stehenní a hýžďové svaly, rozvíjí kontrolu pohybu v kolenou a kyčlích.`,steps:[`Postavte se s chodidly na šířku ramen.`,`Posuňte pánev dozadu a pokrčte kolena, přičemž se spouštějte dolů.`,`Klesněte do pohodlné hloubky se zády rovnými.`,`Odrazte se chodidly a vraťte se do výchozí polohy.`],warnings:[`Pokud se objeví bolest v kolenou, cvik přerušte.`],techniqueNotes:[`Kolena směřují stejným směrem jako špičky.`,`Nezvedejte paty od podlahy.`]},"split-squat":{name:`Dřep s rozkročením`,description:`Dřep v poloze širokého kroku. Posiluje čtyřhlavý sval stehenní a hýžďové svaly každé nohy zvlášť a zlepšuje rovnováhu.`,steps:[`Zaujměte široký výpad: jedna noha vpředu, druhá vzadu.`,`Klesněte svisle dolů a pokrčte obě kolena.`,`Vystoupejte nahoru odrazem přední nohy.`,`Proveďte všechna opakování a vyměňte nohy.`],warnings:[`Pokud se objeví bolest v kolenou, cvik přerušte.`],techniqueNotes:[`Držte trup svisle.`,`Váha těla je převážně na přední noze.`]},"reverse-lunge":{name:`Výpady vzad`,description:`Výpad s krokem vzad. Posiluje čtyřhlavý sval stehenní a hýžďové svaly, rozvíjí rovnováhu a koordinaci.`,steps:[`Postavte se zpříma s chodidly na šířku boků.`,`Udělejte krok vzad a klesněte pokrčením obou kolen.`,`Odrazte se přední nohou a vraťte se do výchozí polohy.`,`Střídejte nohy nebo proveďte všechna opakování na jednu stranu.`],warnings:[`Pokud se objeví bolest v kolenou, cvik přerušte.`],techniqueNotes:[`Krok vzad dělejte kontrolovaně, bez škubnutí.`,`Držte trup zpříma.`]},"glute-bridge":{name:`Hýžďový most`,description:`Zvedání pánve vleže na zádech. Posiluje hýžďové svaly a zadní stranu stehen.`,steps:[`Lehněte si na záda, pokrčte kolena, chodidla na podlaze.`,`Zatněte hýždě a zvedněte pánev nahoru.`,`V horní poloze vydržte vteřinu.`,`Pomalu spusťte pánev zpět na podlahu.`],warnings:[`Pokud cítíte bolest v bederní oblasti, cvik přerušte.`],techniqueNotes:[`V horní poloze neprohýbejte bedra.`,`Tlačte patami do podlahy.`]},"single-leg-glute-bridge":{name:`Hýžďový most na jedné noze`,description:`Náročnější varianta hýžďového mostu s oporou o jednu nohu. Posiluje hýžďové svaly a zadní stranu stehen, zlepšuje stabilitu pánve.`,steps:[`Lehněte si na záda, pokrčte kolena, chodidla na podlaze.`,`Natáhněte jednu nohu a zvedněte ji nad podlahu.`,`Zvedněte pánev odrazem paty opěrné nohy.`,`Pomalu klesněte; po sérii vyměňte nohy.`],warnings:[`Pokud cítíte bolest v bederní oblasti, cvik přerušte.`],techniqueNotes:[`Držte pánev rovně, nenaklánějte ji.`,`Pohybujte se pomalu a kontrolovaně.`]},"knee-push-up":{name:`Kliky na kolenou`,description:`Usnadněná varianta kliků s oporou o kolena. Posiluje prsní svaly a tricepsy.`,steps:[`Klekněte si, dlaně na podlaze o něco širší než ramena.`,`Vyrovnejte tělo od kolen po hlavu.`,`Pokrčte paže a spusťte hrudník k podlaze.`,`Odrazte se a napněte paže.`],warnings:[`Pokud se objeví bolest v zápěstích nebo ramenou, cvik přerušte.`],techniqueNotes:[`Lokty v úhlu přibližně 45° od trupu.`,`Neprověšujte se v bedrech.`]},"push-up":{name:`Kliky`,description:`Klasické kliky od podlahy. Posilují prsní svaly, tricepsy a stabilizátory trupu.`,steps:[`Zaujměte polohu vzporu ležmo, dlaně o něco širší než ramena.`,`Vyrovnejte tělo od pat po hlavu.`,`Pokrčte paže a spusťte hrudník k podlaze.`,`Odrazte se a napněte paže.`],warnings:[`Pokud se objeví bolest v zápěstích nebo ramenou, cvik přerušte.`],techniqueNotes:[`Držte břišní svaly a hýždě napnuté.`,`Lokty v úhlu přibližně 45° od trupu.`]},"wall-push-up":{name:`Kliky o zeď`,description:`Nejlehčí varianta kliků s oporou o zeď. Posiluje prsní svaly a tricepsy s minimální zátěží.`,steps:[`Postavte se čelem ke zdi na vzdálenost natažených paží.`,`Opřete dlaně o zeď ve výšce ramen.`,`Pokrčte paže a přibližte hrudník ke zdi.`,`Odrazte se a vraťte se do výchozí polohy.`],warnings:[`Pokud se objeví bolest v ramenou, cvik přerušte.`],techniqueNotes:[`Držte tělo rovné jako prkno.`,`Čím dál jsou chodidla od zdi, tím je cvik těžší.`]},"pike-push-up":{name:`Kliky v pozici „štika“`,description:`Kliky se zvednutou pánví, které přesouvají zátěž na ramena. Posilují deltové svaly a tricepsy.`,steps:[`Zaujměte polohu vzporu ležmo a zvedněte pánev tak, aby vzniklo obrácené písmeno „V“.`,`Pokrčte paže a spusťte hlavu směrem k podlaze mezi dlaně.`,`Odrazte se a napněte paže.`,`Po celou sérii držte pánev vysoko.`],warnings:[`Spouštějte se pomalu a neopírejte se hlavou o podlahu.`,`Pokud se objeví bolest v ramenou, zápěstích nebo krku, cvik přerušte.`],techniqueNotes:[`Lokty směřují dozadu, ne do stran.`,`Pohled na podlahu mezi dlaněmi.`]},plank:n,"side-plank":{name:`Boční prkno`,description:`Statické držení těla na boku s oporou o předloktí. Posiluje šikmé břišní svaly a stabilizátory trupu.`,steps:[`Lehněte si na bok, loket pod ramenem.`,`Položte chodidla na sebe nebo jedno před druhé.`,`Zvedněte pánev a vyrovnejte tělo do jedné linie.`,`Vydržte v poloze stanovený čas, pak vyměňte stranu.`],warnings:[`Pokud se objeví bolest v rameni, cvik přerušte.`],techniqueNotes:[`Nedovolte pánvi, aby se prověsila.`,`Držte krk v jedné linii s tělem.`]},"dead-bug":{name:`Mrtvý brouk`,description:`Střídavé natahování protilehlé paže a nohy vleže na zádech. Posiluje hluboké svaly trupu a kontrolu polohy beder.`,steps:[`Lehněte si na záda, paže natáhněte vzhůru, nohy pokrčte v pravém úhlu.`,`Pomalu spusťte protilehlou paži a nohu k podlaze.`,`Vraťte je do výchozí polohy.`,`Opakujte s druhou dvojicí paže a nohy.`],warnings:[],techniqueNotes:[`Přitlačujte bedra k podlaze.`,`Pohybujte se pomalu, při spouštění vydechujte.`]},"bird-dog":{name:`Pták a pes`,description:`Střídavé natahování protilehlé paže a nohy v podporu na kolenou. Posiluje svaly trupu, hýždě a koordinaci.`,steps:[`Zaujměte polohu na čtyřech, dlaně pod rameny, kolena pod boky.`,`Současně natáhněte jednu paži dopředu a protilehlou nohu dozadu.`,`Na vteřinu vydržte.`,`Vraťte se do výchozí polohy a vyměňte stranu.`],warnings:[`Pokud se objeví bolest v zápěstích, cvik přerušte.`],techniqueNotes:[`Držte záda rovně, neprohýbejte se.`,`Pánev zůstává rovnoběžně s podlahou.`]},superman:a,"wall-sit":{name:`Židle u zdi`,description:`Statické držení polohy vsedě zády ke zdi. Posiluje čtyřhlavý sval stehenní a vytrvalost nohou.`,steps:[`Postavte se zády ke zdi, chodidla zhruba půl metru od ní.`,`Sklouzávejte zády dolů, dokud se kolena nepokrčí v pohodlném úhlu.`,`Vydržte v poloze stanovený čas.`,`Pomalu se zvedněte nahoru.`],warnings:[`Pokud se objeví bolest v kolenou, cvik přerušte.`],techniqueNotes:[`Kolena nad kotníky, nepřesahují špičky.`,`Záda jsou celá přitisknutá ke zdi.`]},"jumping-jacks":{name:`Panák`,description:`Skoky s rozpažením a roznožením. Rozvíjejí kardiovaskulární vytrvalost a prohřívají celé tělo.`,steps:[`Postavte se zpříma, nohy u sebe, paže podél těla.`,`Skokem rozkročte nohy a zvedněte paže nad hlavu.`,`Skokem se vraťte do výchozí polohy.`,`Pokračujte rovnoměrným tempem stanovený čas.`],warnings:[`Dopadejte měkce na přední část chodidla.`,`Pokud se objeví bolest v kolenou nebo kotnících, cvik přerušte.`],techniqueNotes:[`Kolena při dopadu mírně pokrčená.`,`Dýchejte rovnoměrně.`]},"step-jacks":{name:`Panák s kroky`,description:`Bezrázová varianta panáka: krok do strany se zvednutím paží nad hlavu. Prohřívá tělo a zvyšuje tep bez skákání.`,steps:[`Postavte se zpříma, nohy u sebe, paže podél těla.`,`Udělejte krok do strany a současně zvedněte paže nad hlavu.`,`Přistavte nohu a spusťte paže.`,`Střídejte strany rovnoměrným tempem.`],warnings:[],techniqueNotes:[`Držte tempo, aby tep mírně rostl.`,`Našlapujte měkce.`]},"high-knees":{name:`Běh s vysokým zdvihem kolen`,description:`Běh na místě s vysokým zvedáním kolen. Rozvíjí kardiovaskulární vytrvalost a rychlost nohou.`,steps:[`Postavte se zpříma, chodidla na šířku boků.`,`Začněte běžet na místě a zvedejte kolena přibližně do úrovně boků.`,`Pracujte pažemi v rytmu nohou.`,`Pokračujte stanovený čas.`],warnings:[`Dopadejte měkce na přední část chodidla.`,`Pokud se objeví bolest v kolenou nebo kotnících, cvik přerušte.`],techniqueNotes:[`Držte trup svisle.`,`Nenaklánějte se dozadu.`]},"march-in-place":{name:`Pochod na místě`,description:`Chůze na místě s aktivní prací paží. Lehký bezrázový kardio cvik na rozehřátí a zvýšení tepu.`,steps:[`Postavte se zpříma, paže pokrčené v loktech.`,`Střídavě zvedejte kolena a pochodujte na místě.`,`Pracujte pažemi v rytmu kroků.`,`Udržujte rovnoměrné tempo stanovený čas.`],warnings:[],techniqueNotes:[`Držte záda rovně.`,`Pro ztížení zvedejte kolena výš nebo zrychlete tempo.`]},"mountain-climbers":{name:`Horolezec`,description:`Střídavé přitahování kolen k hrudníku ve vzporu ležmo. Rozvíjí vytrvalost a posiluje svaly trupu.`,steps:[`Zaujměte vzpor ležmo, dlaně pod rameny.`,`Přitáhněte jedno koleno k hrudníku.`,`Vraťte nohu zpět a přitáhněte druhé koleno.`,`Střídejte nohy rychlým, ale kontrolovaným tempem.`],warnings:[`Pokud se objeví bolest v zápěstích nebo ramenou, cvik přerušte.`],techniqueNotes:[`Pánev nezvedejte vysoko.`,`Ramena držte nad dlaněmi.`]},burpee:t,"squat-jump":{name:`Dřep s výskokem`,description:`Dřep s výbušným výskokem. Rozvíjí sílu nohou a výbušnost.`,steps:[`Postavte se s chodidly na šířku ramen.`,`Podřepněte do pohodlné hloubky.`,`Výbušně vyskočte nahoru.`,`Měkce dopadněte a okamžitě přejděte do dřepu.`],warnings:[`Dopadejte měkce na pokrčené nohy.`,`Pokud se objeví bolest v kolenou nebo kotnících, cvik přerušte.`],techniqueNotes:[`Kolena směřují stejným směrem jako špičky.`,`Dopad je tichý a kontrolovaný.`]},"cat-cow":{name:`Kočka a kráva`,description:`Plynulé střídavé zakulacování a prohýbání zad v podporu na kolenou. Zlepšuje pohyblivost páteře.`,steps:[`Zaujměte polohu na čtyřech, dlaně pod rameny.`,`Při nádechu prohněte záda a zvedněte pohled.`,`Při výdechu zakulaťte záda a svěste hlavu.`,`Opakujte plynule v rytmu dýchání.`],warnings:[`Pohybujte se v pohodlném rozsahu a při bolesti přestaňte.`],techniqueNotes:[`Pohyb jde od pánve k hlavě.`,`Nespěchejte.`]},"kneeling-hip-flexor-stretch":{name:`Protažení ohybačů kyčle v kleku`,description:`Protažení přední strany stehna v poloze výpadu na koleni. Zlepšuje pohyblivost kyčelního kloubu.`,steps:[`Klekněte na jedno koleno, druhá noha je vpředu pokrčená v pravém úhlu.`,`Zatněte hýždě nohy, která klečí.`,`Plynule posouvejte pánev dopředu, dokud neucítíte protažení.`,`Vydržte v poloze stanovený čas a vyměňte nohu.`],warnings:[`Podložte koleno něčím měkkým; při bolesti přestaňte.`],techniqueNotes:[`Neprohýbejte bedra.`,`Protažení má být mírné, bez bolesti.`]},"arm-circles":{name:`Kroužení pažemi`,description:`Kruhové pohyby nataženými pažemi. Prohřívá ramenní klouby a zlepšuje jejich pohyblivost.`,steps:[`Postavte se zpříma a rozpažte.`,`Provádějte malé kruhy pažemi dopředu.`,`Postupně zvětšujte rozsah.`,`Po polovině času změňte směr.`],warnings:[`Pokud se objeví bolest v ramenou, cvik přerušte.`],techniqueNotes:[`Ramena držte dole, netahejte je k uším.`,`Pohybujte se plynule.`]},"open-book-rotation":{name:`Rotace „otevřená kniha“`,description:`Rotace hrudní páteře vleže na boku. Zlepšuje pohyblivost hrudní páteře a ramen.`,steps:[`Lehněte si na bok, pokrčte kolena, paže natáhněte před sebe.`,`Veďte horní paži obloukem na opačnou stranu a otáčejte hrudník.`,`Sledujte pohledem ruku.`,`Vraťte paži zpět; po sérii vyměňte stranu.`],warnings:[`Pohybujte se v pohodlném rozsahu a při bolesti přestaňte.`],techniqueNotes:[`Kolena zůstávají spolu na podlaze.`,`Dýchejte klidně.`]},"goblet-squat":{name:`Goblet dřep`,description:`Dřep s činkou nebo kettlebellem u hrudníku. Posiluje čtyřhlavý sval stehenní a hýždě a pomáhá držet trup svisle.`,steps:[`Držte činku nebo kettlebell svisle u hrudníku.`,`Postavte se s chodidly o něco šířeji než ramena.`,`Podřepněte a držte hrudník vzpřímený.`,`Vstaňte odrazem chodidel.`],warnings:[`Pokud se objeví bolest v kolenou nebo zádech, cvik přerušte.`],techniqueNotes:[`Lokty se pohybují mezi koleny.`,`Záda jsou rovná po celou dobu pohybu.`]},"dumbbell-romanian-deadlift":{name:`Rumunský mrtvý tah s činkami`,description:`Předklon s jednoručkami za pomoci pohybu v kyčelních kloubech. Posiluje zadní stranu stehen a hýždě.`,steps:[`Postavte se zpříma s činkami před stehny.`,`Lehce pokrčte kolena a posuňte pánev dozadu.`,`Spouštějte činky podél nohou, dokud neucítíte protažení zadní strany stehen.`,`Vraťte se nahoru posunem pánve dopředu.`],warnings:[`Nezakulacujte záda; zvolte váhu, se kterou udržíte techniku.`,`Pokud se objeví bolest v bederní oblasti, cvik přerušte.`],techniqueNotes:[`Záda rovná, činky blízko nohou.`,`Pohyb vychází z pánve, ne ze zad.`]},"one-arm-dumbbell-row":{name:`Přítah jednoruční činky`,description:`Přítah činky k pasu v předklonu s opřenou rukou. Posiluje svaly zad a bicepsy.`,steps:[`Předkloňte se a volnou rukou se opřete o stehno nebo stabilní oporu.`,`Uchopte činku, paže natažená pod ramenem.`,`Přitáhněte činku k pasu a veďte loket dozadu.`,`Pomalu spusťte; po sérii vyměňte ruku.`],warnings:[`Držte záda rovně; při bolesti v bederní oblasti přestaňte.`],techniqueNotes:[`Při přítahu netočte trupem.`,`Stahujte lopatku k páteři.`]},"dumbbell-floor-press":{name:`Tlak s činkami vleže na podlaze`,description:`Tlak jednoruček vzhůru vleže na podlaze s omezeným rozsahem. Posiluje prsní svaly a tricepsy.`,steps:[`Lehněte si na záda, pokrčte kolena, činky držte u hrudníku.`,`Vytlačte činky vzhůru nad hrudník.`,`Pomalu spouštějte, dokud se ramena nedotknou podlahy.`,`Opakujte tlak.`],warnings:[`Pokud se objeví bolest v ramenou, cvik přerušte.`],techniqueNotes:[`Lokty v úhlu přibližně 45° od trupu.`,`Spouštějte činky kontrolovaně, bez úderu o podlahu.`]},"dumbbell-bench-press":{name:`Tlak s činkami vleže na lavici`,description:`Tlak jednoruček vzhůru vleže na vodorovné lavici. Posiluje prsní svaly a tricepsy.`,steps:[`Lehněte si na lavici, chodidla na podlaze, činky u hrudníku.`,`Vytlačte činky vzhůru nad hrudník.`,`Pomalu je spusťte do úrovně hrudníku.`,`Opakujte tlak.`],warnings:[`Zvolte váhu, kterou dokážete kontrolovaně spustit.`,`Pokud se objeví bolest v ramenou, cvik přerušte.`],techniqueNotes:[`Lopatky stažené a přitisknuté k lavici.`,`Neodrážejte činky od hrudníku.`]},"incline-dumbbell-press":{name:`Tlak s činkami na šikmé lavici`,description:`Tlak jednoruček vleže na lavici se zvednutým opěradlem. Posiluje horní část prsních svalů a přední deltové svaly.`,steps:[`Nastavte opěradlo lavice do mírného sklonu.`,`Sedněte si na lavici, záda přitisknutá, činky u hrudníku.`,`Vytlačte činky vzhůru nad horní část hrudníku.`,`Pomalu spusťte a opakujte.`],warnings:[`Ujistěte se, že je opěradlo lavice bezpečně zajištěno.`,`Pokud se objeví bolest v ramenou, cvik přerušte.`],techniqueNotes:[`Lopatky stažené a přitisknuté k lavici.`,`Pohybujte se kontrolovaně v celém rozsahu.`]},"dumbbell-shoulder-press":{name:`Tlak s činkami nad hlavu`,description:`Tlak jednoruček vzhůru ve stoje. Posiluje deltové svaly a tricepsy.`,steps:[`Postavte se zpříma, činky ve výšce ramen.`,`Zatněte břišní svaly a hýždě.`,`Vytlačte činky vzhůru nad hlavu.`,`Pomalu spusťte do úrovně ramen.`],warnings:[`Při tlaku neprohýbejte bedra.`,`Pokud se objeví bolest v ramenou, krku nebo zádech, cvik přerušte.`],techniqueNotes:[`Žebra stažená dolů, trup stabilní.`,`Nezaklánějte hlavu dozadu.`]},"dumbbell-reverse-lunge":{name:`Výpady vzad s činkami`,description:`Výpad s krokem vzad s činkami v rukou. Posiluje čtyřhlavý sval stehenní a hýžďové svaly s dodatečnou zátěží.`,steps:[`Postavte se zpříma s činkami v pažích podél těla.`,`Udělejte krok vzad a klesněte pokrčením obou kolen.`,`Odrazte se přední nohou a vraťte se do výchozí polohy.`,`Střídejte nohy nebo proveďte všechna opakování na jednu stranu.`],warnings:[`Pokud se objeví bolest v kolenou, cvik přerušte.`],techniqueNotes:[`Držte trup svisle.`,`Ramena dole, činky se nekývají.`]},"farmer-carry":{name:`Farmářská chůze`,description:`Chůze s činkami nebo kettlebelly v pažích podél těla. Posiluje svaly trupu, úchop a celkovou stabilitu.`,steps:[`Uchopte činky nebo kettlebelly do obou rukou.`,`Vzpřimte se, ramena dole a stažená dozadu.`,`Choďte krátkými rovnoměrnými kroky stanovený čas.`,`Opatrně položte váhu na podlahu.`],warnings:[`Váhu zvedejte a pokládejte s rovnými zády.`,`Pokud se objeví bolest v zádech nebo zápěstích, cvik přerušte.`],techniqueNotes:[`Nenaklánějte se na stranu závaží.`,`Držte břišní svaly napnuté.`]},"kettlebell-swing":{name:`Švih s kettlebellem`,description:`Dynamický švih kettlebellem za pomoci pohybu v kyčelních kloubech. Rozvíjí sílu hýždí a zadní strany stehen a vytrvalost.`,steps:[`Postavte se s chodidly o něco šířeji než ramena, kettlebell před sebou.`,`Předkloňte se s rovnými zády a zaveďte kettlebell dozadu mezi nohy.`,`Prudce posuňte pánev dopředu, aby kettlebell vystoupal do úrovně hrudníku.`,`Nechte kettlebell klesnout a pohyb opakujte.`],warnings:[`Ujistěte se, že kolem nejsou lidé ani předměty.`,`Pokud se objeví bolest v bederní oblasti, cvik přerušte.`],techniqueNotes:[`Pohyb vychází z pánve, paže kettlebell jen drží.`,`Záda jsou v dolní poloze rovná.`]},"kettlebell-deadlift":{name:`Mrtvý tah s kettlebellem`,description:`Zvedání kettlebellu ze země za pomoci pohybu v kyčelních kloubech. Posiluje hýždě a zadní stranu stehen a učí správně zvedat váhu.`,steps:[`Postavte se nad kettlebell, chodidla na šířku boků.`,`Posuňte pánev dozadu, pokrčte kolena a uchopte rukojeť kettlebellu.`,`Vzpřimte se posunem pánve dopředu.`,`Spusťte kettlebell na podlahu stejným pohybem.`],warnings:[`Při zvedání nezakulacujte záda.`,`Pokud se objeví bolest v bederní oblasti, cvik přerušte.`],techniqueNotes:[`Záda rovná, pohled před sebe.`,`Kettlebell se pohybuje blízko těla.`]},"band-pull-apart":{name:`Roztažení gumy`,description:`Natahování odporové gumy rovnými pažemi před hrudníkem. Posiluje svaly horní části zad a zadní deltové svaly.`,steps:[`Uchopte gumu oběma rukama na šířku ramen před hrudníkem.`,`Rozpažte a natáhněte gumu.`,`V koncové poloze stáhněte lopatky k sobě.`,`Pomalu vraťte paže do výchozí polohy.`],warnings:[`Před cvikem zkontrolujte, zda není guma poškozená.`],techniqueNotes:[`Ramena dole, nezvedejte je k uším.`,`Paže jsou po celou dobu pohybu téměř natažené.`]},"band-row":{name:`Přítah gumy k pasu`,description:`Přítah upevněné odporové gumy k pasu. Posiluje svaly zad a bicepsy.`,steps:[`Upevněte gumu ve výšce pasu za pevnou oporu.`,`Uchopte konce a ustupte dozadu, až se guma napne.`,`Přitáhněte ruce k pasu a veďte lokty dozadu.`,`Pomalu vraťte ruce dopředu.`],warnings:[`Zkontrolujte, zda je upevnění pevné a guma není poškozená.`],techniqueNotes:[`V koncové poloze stáhněte lopatky k sobě.`,`Trup zůstává v klidu, nenaklánějte se dozadu.`]},"band-lat-pulldown":{name:`Stahování gumy shora`,description:`Stahování gumy upevněné nahoře dolů k hrudníku. Posiluje široký sval zádový a bicepsy.`,steps:[`Upevněte gumu nad hlavou za pevnou oporu.`,`Uchopte konce, paže natažené vzhůru.`,`Stahujte lokty dolů k bokům a přibližujte ruce k hrudníku.`,`Pomalu vraťte paže nahoru.`],warnings:[`Zkontrolujte, zda je horní upevnění pevné a guma není poškozená.`,`Pokud se objeví bolest v ramenou, cvik přerušte.`],techniqueNotes:[`Před stahováním spusťte lopatky dolů.`,`Nerozhoupávejte trup.`]},"pull-up":{name:`Shyby`,description:`Přitahování těla na hrazdě do úrovně brady. Posiluje svaly zad a bicepsy.`,steps:[`Uchopte hrazdu nadhmatem o něco širším než ramena.`,`Zavěste se na natažených pažích a stáhněte lopatky dolů.`,`Přitáhněte se, dokud se brada nedostane nad hrazdu.`,`Pomalu se spusťte do natažených paží.`],warnings:[`Používejte jen bezpečně upevněnou hrazdu.`,`Pokud se objeví bolest v ramenou nebo zápěstích, cvik přerušte.`],techniqueNotes:[`Nehoupejte se a nedělejte škubavé pohyby.`,`Spouštějte se kontrolovaně.`]},"dead-hang":{name:`Vis na hrazdě`,description:`Statický vis na hrazdě na natažených pažích. Posiluje úchop a svaly ramenního pletence.`,steps:[`Uchopte hrazdu úchopem na šířku ramen.`,`Opatrně se zavěste na natažených pažích.`,`Vydržte v poloze stanovený čas a dýchejte rovnoměrně.`,`Opatrně se postavte na podlahu.`],warnings:[`Používejte jen bezpečně upevněnou hrazdu.`,`Pokud se objeví bolest v ramenou nebo zápěstích, cvik přerušte.`],techniqueNotes:[`Ramena lehce zapojte, neprověšujte se pasivně.`,`Nehoupejte se.`]},"hanging-knee-raise":{name:`Zvedání kolen ve visu`,description:`Přitahování kolen k hrudníku ve visu na hrazdě. Posiluje břišní svaly a úchop.`,steps:[`Zavěste se na hrazdě na natažených pažích.`,`Zatněte břišní svaly a přitáhněte kolena k hrudníku.`,`Na vteřinu vydržte.`,`Pomalu spusťte nohy bez houpání.`],warnings:[`Používejte jen bezpečně upevněnou hrazdu.`,`Pokud se objeví bolest v ramenou nebo bedrech, cvik přerušte.`],techniqueNotes:[`Pohybujte se bez škubání a houpání.`,`V horní poloze lehce podsaďte pánev.`]},"jump-rope":{name:`Skákání přes švihadlo`,description:`Rytmické skákání přes švihadlo. Rozvíjí kardiovaskulární vytrvalost, koordinaci a sílu lýtkových svalů.`,steps:[`Uchopte rukojeti švihadla, lano je za patami.`,`Otáčejte lanem zápěstími.`,`Provádějte nízké skoky, když lano prochází pod chodidly.`,`Udržujte rovnoměrný rytmus stanovený čas.`],warnings:[`Skákejte nízko a dopadejte měkce na přední část chodidla.`,`Pokud se objeví bolest v kolenou nebo kotnících, cvik přerušte.`],techniqueNotes:[`Lokty blízko těla.`,`Kolena lehce pokrčená.`]},"step-up":{name:`Výstup na plošinu`,description:`Střídavý výstup na stabilní plošinu každou nohou. Posiluje čtyřhlavý sval stehenní a hýžďové svaly.`,steps:[`Postavte se před plošinu.`,`Postavte na ni celé chodidlo jedné nohy.`,`Vystupte odrazem nohy stojící na plošině.`,`Pomalu sestupte a opakujte; po sérii vyměňte nohu.`],warnings:[`Ujistěte se, že je plošina stabilní a neklouže.`,`Pokud se objeví bolest v kolenou, cvik přerušte.`],techniqueNotes:[`Neodrážejte se spodní nohou.`,`Koleno směřuje stejným směrem jako špička.`]},"barbell-back-squat":{name:`Dřep s velkou činkou na zádech`,description:`Dřep s velkou činkou na horní části zad. Rozvíjí sílu čtyřhlavého svalu stehenního, hýždí a celého těla.`,steps:[`Položte činku na horní část zad a sundejte ji ze stojanu.`,`Ustupte, chodidla na šířku ramen nebo o něco šířeji.`,`Podřepněte do pohodlné hloubky se zády rovnými.`,`Vstaňte a po sérii vraťte činku do stojanu.`],warnings:[`Nastavte bezpečnostní zarážky stojanu a pracujte s váhou, kterou ovládáte.`,`Pokud se objeví bolest v kolenou, zádech nebo ramenou, cvik přerušte.`],techniqueNotes:[`Před každým opakováním napněte trup.`,`Kolena směřují stejným směrem jako špičky.`]},"barbell-deadlift":{name:`Mrtvý tah s velkou činkou`,description:`Zvedání činky ze země do stoje. Rozvíjí sílu zadní strany stehen, hýždí a zad.`,steps:[`Postavte se tak, aby tyč byla nad středem chodidla.`,`Posuňte pánev dozadu, pokrčte kolena a uchopte tyč.`,`Vzpřimte se a držte tyč blízko nohou.`,`Spusťte činku na podlahu stejným pohybem.`],warnings:[`Nezakulacujte záda; pracujte s váhou, kterou ovládáte.`,`Pokud se objeví bolest v bederní oblasti, cvik přerušte.`],techniqueNotes:[`Záda rovná, trup napnutý.`,`Tlačte nohama do podlahy, netahejte zády.`]},"cardio-machine-intervals":{name:`Intervaly na kardio stroji`,description:`Intervalová práce na rotopedu, eliptickém trenažéru nebo jiném kardio stroji. Rozvíjí kardiovaskulární vytrvalost.`,steps:[`Několik minut se rozehřívejte v lehkém tempu.`,`Na stanovenou dobu intervalu zvyšte tempo nebo odpor.`,`Během odpočinku pokračujte v pohybu v lehkém tempu.`,`Opakujte interval stanovený početkrát.`],warnings:[`Před použitím si přečtěte návod ke stroji.`,`Pokud se objeví závrať nebo bolest, snižte tempo nebo přestaňte.`],techniqueNotes:[`Intenzita má být znatelná, ale kontrolovaná.`,`Držte rovnou postavu.`]},"jump-rope-boxer-step":{name:`Boxerský krok se švihadlem`,description:`Nízké skoky přes švihadlo se střídavým přenášením váhy z nohy na nohu. Jednodušší než skoky snožmo.`,steps:[`Uchopte rukojeti švihadla, lano je za patami.`,`Otáčejte lanem zápěstími.`,`Lehce přenášejte váhu z jedné nohy na druhou, jako byste šlapali na místě.`,`Udržujte rovnoměrný rytmus stanovený čas.`],warnings:[`Skákejte nízko a dopadejte měkce na přední část chodidla.`,`Pokud se objeví bolest v kotnících, cvik přerušte.`],techniqueNotes:[`Skok jen pár centimetrů nad podlahu.`,`Lokty blízko těla.`]},"jump-rope-side-to-side":{name:`Skoky přes švihadlo ze strany na stranu`,description:`Skoky snožmo s malým posunem doleva a doprava. Přidávají zátěž na lýtka a trénují koordinaci.`,steps:[`Uchopte rukojeti švihadla, nohy u sebe.`,`Přeskakujte lano s mírným posunem doleva.`,`Při dalším skoku se posuňte doprava.`,`Držte rytmus a dopadejte měkce.`],warnings:[`Ujistěte se, že je dost místa a povrch neklouže.`,`Pokud se objeví bolest v kolenou nebo kotnících, cvik přerušte.`],techniqueNotes:[`Posun je malý, ne širší než chodidla.`,`Kolena lehce pokrčená.`]},"jump-rope-high-knees":{name:`Běh se švihadlem`,description:`Běh na místě přes švihadlo se zvedáním kolen. Intenzivní kardio cvik na vytrvalost.`,steps:[`Uchopte rukojeti švihadla, lano je za patami.`,`Běžte na místě a při každém kroku prohoďte lano pod chodidlem.`,`Zvedejte kolena do úrovně boků.`,`Udržujte tempo stanovený čas.`],warnings:[`Provádějte jen po rozcvičce.`,`Pokud se objeví bolest v kolenou, kyčlích nebo kotnících, cvik přerušte.`],techniqueNotes:[`Trup rovný, nenaklánějte se dozadu.`,`Dopad je měkký, na přední část chodidla.`]},"lateral-step-up":{name:`Boční výstup na step`,description:`Výstup na plošinu bokem k ní. Zatěžuje hýždě a stehenní svaly pod jiným úhlem než běžný výstup.`,steps:[`Postavte se bokem k plošině, bližší noha je na ní.`,`Napněte nohu a vystupte na plošinu.`,`Kontrolovaně sestupte zpět.`,`Dokončete sérii na jedné noze, pak vyměňte nohu.`],warnings:[`Ujistěte se, že je plošina stabilní a neklouže.`,`Pokud se objeví bolest v kolenou nebo kyčlích, cvik přerušte.`],techniqueNotes:[`Pracuje opěrná noha, druhá se jen dotýká.`,`Koleno nezapadá dovnitř.`]},"step-platform-push-up":{name:`Kliky s oporou o step`,description:`Kliky s rukama na plošině. Usnadněná verze klasických kliků pro začátečníky.`,steps:[`Položte ruce na plošinu o něco šířeji než ramena, tělo tvoří přímou linii.`,`Pokrčte lokty a spouštějte hrudník k plošině.`,`Odrazte se a napněte paže.`,`Držte trup napnutý.`],warnings:[`Plošina musí stát stabilně, nejlépe na protiskluzovém povrchu.`,`Pokud se objeví bolest v zápěstích nebo ramenou, cvik přerušte.`],techniqueNotes:[`Neprohýbejte bedra.`,`Lokty v úhlu přibližně 45° od trupu.`]},"step-platform-calf-raise":{name:`Výpony na stepu`,description:`Výpony z okraje plošiny pro větší rozsah pohybu. Posilují lýtkové svaly.`,steps:[`Postavte se na okraj plošiny přední částí chodidel, paty ve vzduchu.`,`Pomalu spusťte paty pod úroveň plošiny.`,`Vystupte na špičky co nejvýš.`,`Opakujte bez škubání.`],warnings:[`Držte se zdi nebo stojanu pro rovnováhu.`,`Pokud se objeví bolest v kotnících nebo Achillově šlase, cvik přerušte.`],techniqueNotes:[`Pohyb je pomalý: 2 vteřiny nahoru, 2 dolů.`,`Kolena téměř natažená.`]},"step-platform-reverse-lunge":{name:`Výpad vzad ze stepu`,description:`Krok vzad z plošiny do výpadu. Zvětšený rozsah pohybu pro hýždě a stehna.`,steps:[`Postavte se na plošinu, nohy na šířku boků.`,`Udělejte jednou nohou krok vzad na podlahu.`,`Klesněte do výpadu, přední noha zůstává na plošině.`,`Vraťte se do výchozí polohy a vyměňte nohu.`],warnings:[`Ujistěte se, že je plošina stabilní a neklouže.`,`Pokud se objeví bolest v kolenou, cvik přerušte.`],techniqueNotes:[`Trup svisle.`,`Přední pata je přitisknutá k plošině.`]},"step-platform-taps":{name:`Dotyky stepu`,description:`Rychlé střídavé dotyky plošiny chodidly. Lehký kardio cvik na rozehřátí a vytrvalost.`,steps:[`Postavte se před plošinu.`,`Dotkněte se plošiny pravým chodidlem, potom levým.`,`Pohybujte se rychle a lehce, nešlapejte na celé chodidlo.`,`Udržujte rytmus stanovený čas.`],warnings:[`Plošina musí stát stabilně.`,`Pokud se objeví bolest v kolenou, cvik přerušte.`],techniqueNotes:[`Záda rovná, paže pracují v rytmu.`,`Pohyby jsou lehké, bez úderů.`]},"bench-dip":{name:`Dipy na lavici`,description:`Dipy na triceps s oporou rukou o lavici za zády.`,steps:[`Sedněte si na okraj lavice, ruce vedle stehen.`,`Posuňte se dopředu a držte se rukama lavice.`,`Pokrčte lokty přibližně na 90°.`,`Napněte paže a vraťte se nahoru.`],warnings:[`Nespouštějte se hluboko, pokud cítíte nepohodlí v ramenou.`,`Lavice musí stát stabilně.`,`Pokud se objeví bolest v ramenou nebo zápěstích, cvik přerušte.`],techniqueNotes:[`Lokty směřují dozadu, ne do stran.`,`Ramena nezvedejte k uším.`]},"bulgarian-split-squat":{name:`Bulharský dřep`,description:`Dřep na jedné noze se zadní nohou na lavici. Silně zatěžuje hýždě a stehna.`,steps:[`Postavte se zády k lavici, položte nárt jedné nohy na lavici.`,`Klesněte pokrčením přední nohy.`,`Vystupte odrazem paty přední nohy.`,`Proveďte všechna opakování, pak vyměňte nohu.`],warnings:[`Lavice musí být stabilní; vzdálenost zvolte tak, aby koleno nepřesahovalo chodidlo.`,`Pokud se objeví bolest v kolenou nebo kyčlích, cvik přerušte.`],techniqueNotes:[`Trup lehce nakloněný dopředu.`,`Hlavní váha je na přední noze.`]},"bench-hip-thrust":{name:`Hýžďový most z lavice`,description:`Zvedání pánve s oporou lopatek o lavici. Základní cvik na hýždě.`,steps:[`Sedněte si na podlahu zády k lavici, lopatky na okraji lavice.`,`Pokrčte kolena, chodidla na podlaze.`,`Zvedněte pánev, dokud trup a stehna nevytvoří jednu linii.`,`Na okamžik vydržte a klesněte.`],warnings:[`Lavice musí být nehybná, nejlépe u zdi.`,`Pokud se objeví bolest v bederní oblasti, cvik přerušte.`],techniqueNotes:[`Brada mírně přitažená k hrudníku.`,`Nahoře neprohýbejte bedra.`]},"chest-supported-dumbbell-row":{name:`Přítah činek s opřením o lavici`,description:`Přítah jednoruček vleže hrudníkem na šikmé lavici. Odlehčuje bedra a soustředí zátěž na záda.`,steps:[`Lehněte si hrudníkem na lavici, v každé ruce činku.`,`Přitáhněte činky k bokům trupu a stahujte lopatky k sobě.`,`Na okamžik vydržte.`,`Kontrolovaně spusťte činky.`],warnings:[`Lavice musí stát stabilně.`,`Pokud se objeví bolest v ramenou, cvik přerušte.`],techniqueNotes:[`Hlava pokračuje v linii páteře.`,`Nerozhoupávejte trup.`]},"kettlebell-single-arm-row":{name:`Přítah kettlebellu jednou rukou`,description:`Přítah kettlebellu v předklonu s opřením volné ruky. Posiluje záda a biceps.`,steps:[`Předkloňte se s rovnými zády, volnou rukou se opřete o stehno.`,`Uchopte kettlebell druhou rukou.`,`Přitáhněte kettlebell k pasu a stáhněte lopatku.`,`Pomalu kettlebell spusťte.`],warnings:[`Držte záda rovně.`,`Pokud se objeví bolest v bederní oblasti, cvik přerušte.`],techniqueNotes:[`Loket se pohybuje podél trupu.`,`Pohled směřuje do podlahy.`]},"kettlebell-overhead-press":{name:`Tlak s kettlebellem nad hlavu`,description:`Tlak kettlebellu ve stoje jednou rukou. Posiluje ramena, triceps a střed těla.`,steps:[`Zvedněte kettlebell k rameni, loket přitisknutý k trupu.`,`Zatněte břišní svaly a hýždě.`,`Napněte paži vzhůru nad hlavu.`,`Pomalu vraťte kettlebell k rameni.`],warnings:[`Ujistěte se, že nad vámi je dostatek místa.`,`Pokud se objeví bolest v ramenou, krku nebo bedrech, cvik přerušte.`],techniqueNotes:[`Neprohýbejte bedra.`,`Zápěstí rovné, kettlebell leží na předloktí.`]},"kettlebell-halo":{name:`Halo s kettlebellem`,description:`Kruhové pohyby kettlebellu kolem hlavy. Prohřívá ramena a procvičuje stabilitu trupu.`,steps:[`Postavte se zpříma, držte kettlebell dnem vzhůru u hrudníku.`,`Veďte kettlebell kolem hlavy jedním směrem.`,`Vraťte ho k hrudníku.`,`Opakujte opačným směrem.`],warnings:[`Používejte lehký kettlebell.`,`Držte kettlebell pevně, abyste se neuhodili.`,`Pokud se objeví bolest v ramenou nebo krku, cvik přerušte.`],techniqueNotes:[`Trup je v klidu, pracují jen paže.`,`Lokty blízko hlavy.`]},"kettlebell-sumo-deadlift":{name:`Sumo mrtvý tah s kettlebellem`,description:`Tah kettlebellu v širokém postoji. Zatěžuje hýždě a vnitřní stranu stehen.`,steps:[`Postavte se široce, špičky rozvedené, kettlebell mezi chodidly.`,`Posuňte pánev dozadu a uchopte kettlebell.`,`Vzpřimte se tlakem nohou do podlahy.`,`Pomalu kettlebell spusťte.`],warnings:[`Nezakulacujte záda.`,`Pokud se objeví bolest v bederní oblasti nebo kyčlích, cvik přerušte.`],techniqueNotes:[`Kolena směřují stejným směrem jako špičky.`,`Záda rovná po celou dobu pohybu.`]},"kettlebell-reverse-lunge":{name:`Výpad vzad s kettlebellem`,description:`Výpad vzad s kettlebellem u hrudníku. Přidává zátěž na nohy a hýždě.`,steps:[`Držte kettlebell u hrudníku oběma rukama.`,`Udělejte krok vzad a klesněte do výpadu.`,`Odrazte se přední nohou a vraťte se.`,`Vyměňte nohu.`],warnings:[`Pokud se objeví bolest v kolenou, cvik přerušte.`],techniqueNotes:[`Trup svisle.`,`Přední pata je přitisknutá k podlaze.`]},"band-squat":{name:`Dřep s gumou`,description:`Dřep s gumou pod chodidly. Guma přidává odpor při vstávání.`,steps:[`Postavte se na střed gumy, konce držte ve výšce ramen.`,`Podřepněte a posuňte pánev dozadu.`,`Vstaňte natažením nohou.`,`Gumu nepouštějte prudce.`],warnings:[`Zkontrolujte, zda guma není poškozená.`,`Pokud se objeví bolest v kolenou, cvik přerušte.`],techniqueNotes:[`Kolena směřují stejným směrem jako špičky.`,`Záda rovná.`]},"band-chest-press":{name:`Tlak gumy od hrudníku`,description:`Tlak gumy před sebe ve stoje. Posiluje hrudník a triceps bez činek.`,steps:[`Veďte gumu za zády pod lopatkami, konce držte v rukou.`,`Pokrčte lokty, ruce ve výšce hrudníku.`,`Natáhněte paže dopředu.`,`Pomalu se vraťte.`],warnings:[`Zkontrolujte, zda guma není poškozená a pevně leží za zády.`,`Pokud se objeví bolest v ramenou, cvik přerušte.`],techniqueNotes:[`Lokty mírně pod úrovní ramen.`,`Trup je v klidu.`]},"band-overhead-press":{name:`Tlak gumy nad hlavu`,description:`Tlak gumy vzhůru se stoje na ní. Posiluje ramena a triceps.`,steps:[`Postavte se na gumu, konce držte ve výšce ramen.`,`Napněte paže vzhůru nad hlavu.`,`Pomalu je spusťte k ramenům.`,`Neprohýbejte bedra.`],warnings:[`Ujistěte se, že nad vámi je dostatek místa.`,`Pokud se objeví bolest v ramenou nebo krku, cvik přerušte.`],techniqueNotes:[`Břišní svaly napjaté.`,`Paže se pohybují svisle.`]},"band-good-morning":{name:`Předklony s gumou`,description:`Předklony trupu s rovnými zády, guma na ramenou a pod chodidly. Učí pohyb v kyčlích.`,steps:[`Postavte se na gumu, druhý konec přeložte přes ramena.`,`Posuňte pánev dozadu a předkloňte trup s rovnými zády.`,`Klesněte, dokud neucítíte protažení zadní strany stehen.`,`Vzpřimte se a tlačte pánev dopředu.`],warnings:[`Nezakulacujte záda.`,`Zkontrolujte, zda je guma bezpečně upevněna.`,`Pokud se objeví bolest v bederní oblasti, cvik přerušte.`],techniqueNotes:[`Kolena lehce pokrčená.`,`Pohled směřuje dolů a dopředu.`]},"band-bicep-curl":{name:`Zdvih s gumou na biceps`,description:`Zdvih na biceps s odporem gumy.`,steps:[`Postavte se na gumu, konce v rukou, dlaně dopředu.`,`Pokrčte lokty a zvedejte ruce k ramenům.`,`Na okamžik vydržte.`,`Pomalu spusťte ruce.`],warnings:[`Zkontrolujte, zda guma není poškozená.`],techniqueNotes:[`Lokty přitisknuté k bokům.`,`Trup se nehoupe.`]},"scapular-pull-up":{name:`Lopatkové shyby`,description:`Zvedání a spouštění lopatek ve visu bez pokrčení paží. Připravuje ramena na shyby.`,steps:[`Zavěste se na hrazdě, paže rovné.`,`Stáhněte ramena dolů a lopatky k sobě, čímž zvednete tělo o pár centimetrů.`,`Pomalu se vraťte do visu.`,`Nepokrčujte lokty.`],warnings:[`Používejte jen bezpečně upevněnou hrazdu.`,`Pokud se objeví bolest v ramenou nebo zápěstích, cvik přerušte.`],techniqueNotes:[`Pohyb je malý, jen v lopatkách.`,`Tělo se nehoupe.`]},"negative-pull-up":{name:`Negativní shyby`,description:`Pomalé spouštění z horní polohy shybu. Pomáhá naučit se shyby.`,steps:[`Postavte se na židli a uchopte hrazdu, brada nad ní.`,`Odstraňte oporu.`,`Pomalu se spouštějte, dokud se paže nenatáhnou (3–5 vteřin).`,`Vraťte se na židli a opakujte.`],warnings:[`Používejte jen bezpečně upevněnou hrazdu.`,`Použijte židli k zaujetí horní polohy.`,`Pokud se objeví bolest v ramenou nebo zápěstích, cvik přerušte.`],techniqueNotes:[`Spouštějte se kontrolovaně, bez pádu.`,`Lopatky zůstávají stažené dolů.`]},"chin-up":{name:`Shyby podhmatem`,description:`Shyby s dlaněmi k sobě. Zapojují biceps více než běžné shyby.`,steps:[`Uchopte hrazdu podhmatem na šířku ramen.`,`Přitáhněte se, dokud se brada nedostane nad hrazdu.`,`Na okamžik vydržte.`,`Pomalu se spusťte do visu.`],warnings:[`Používejte jen bezpečně upevněnou hrazdu.`,`Pokud se objeví bolest v ramenou, loktech nebo zápěstích, cvik přerušte.`],techniqueNotes:[`Nehoupejte se.`,`Lokty se pohybují dolů a k trupu.`]},"hanging-leg-raise":{name:`Zvedání natažených nohou ve visu`,description:`Zvedání natažených nohou ve visu na hrazdě. Náročnější varianta pro břišní svaly.`,steps:[`Zavěste se na hrazdě.`,`Zatněte břišní svaly a zvedněte natažené nohy do úrovně pánve.`,`Na okamžik vydržte.`,`Pomalu spusťte nohy.`],warnings:[`Používejte jen bezpečně upevněnou hrazdu.`,`Nehoupejte se, nohy zvedejte pomalu.`,`Pokud se objeví bolest v ramenou nebo bedrech, cvik přerušte.`],techniqueNotes:[`Pánev lehce podsazená.`,`Bez houpání těla.`]},"dumbbell-lateral-raise":{name:`Upažování s činkami`,description:`Zvedání jednoruček do stran do úrovně ramen. Rozvíjí střední hlavy deltových svalů.`,steps:[`Postavte se zpříma, činky u boků.`,`Lehce pokrčte lokty a zvedněte paže do stran do úrovně ramen.`,`Pomalu spusťte paže.`,`Nezvedejte ramena k uším.`],warnings:[`Zvolte lehké činky.`,`Pokud se objeví bolest v ramenou nebo krku, cvik přerušte.`],techniqueNotes:[`Lokty mírně výš než ruce.`,`Trup je v klidu.`]},"dumbbell-bicep-curl":{name:`Zdvih s činkami na biceps`,description:`Klasický zdvih paží na biceps ve stoje.`,steps:[`Postavte se zpříma, činky ve svěšených pažích, dlaně dopředu.`,`Pokrčte lokty a zvedejte činky k ramenům.`,`Na okamžik vydržte.`,`Pomalu spusťte činky.`],warnings:[`Volte váhu, se kterou nemusíte houpat trupem.`],techniqueNotes:[`Lokty přitisknuté k bokům.`,`Nenaklánějte se dozadu.`]},"dumbbell-overhead-triceps-extension":{name:`Francouzský tlak s činkou`,description:`Natahování paží s činkou za hlavou. Izoluje triceps.`,steps:[`Postavte se zpříma, obouruč držte činku nad hlavou.`,`Pokrčte lokty a spouštějte činku za hlavu.`,`Napněte paže vzhůru.`,`Lokty držte blízko hlavy.`],warnings:[`Držte činku oběma rukama.`,`Pokud se objeví bolest v ramenou, loktech nebo krku, cvik přerušte.`],techniqueNotes:[`Lokty se nerozevírají do stran.`,`Břišní svaly napjaté.`]},"dumbbell-sumo-squat":{name:`Sumo dřep s činkou`,description:`Dřep v širokém postoji s činkou mezi nohama. Důraz na hýždě a vnitřní stranu stehen.`,steps:[`Postavte se široce, špičky rozvedené, činku držte oběma rukama dole.`,`Podřepněte, kolena směřují stejným směrem jako špičky.`,`Vstaňte tlakem nohou do podlahy.`,`Držte trup svisle.`],warnings:[`Pokud se objeví bolest v kolenou nebo kyčlích, cvik přerušte.`],techniqueNotes:[`Záda rovná.`,`Kolena nezapadají dovnitř.`]},"dumbbell-glute-bridge":{name:`Hýžďový most s činkou`,description:`Hýžďový most s činkou na pánvi. Přidává zátěž na hýždě.`,steps:[`Lehněte si na záda, kolena pokrčená, činka na pánvi.`,`Zvedněte pánev a vyrovnejte tělo do jedné linie.`,`Na okamžik vydržte.`,`Pomalu klesněte.`],warnings:[`Držte činku pevně.`,`Pokud se objeví bolest v bederní oblasti, cvik přerušte.`],techniqueNotes:[`Neprohýbejte bedra.`,`Paty přitisknuté k podlaze.`]},"dumbbell-bent-over-row":{name:`Přítah činek v předklonu`,description:`Přítah dvou činek k pasu v předklonu. Posiluje záda a biceps.`,steps:[`Předkloňte se s rovnými zády, činky ve svěšených pažích.`,`Přitáhněte činky k bokům a stahujte lopatky.`,`Na okamžik vydržte.`,`Pomalu činky spusťte.`],warnings:[`Držte záda rovně.`,`Pokud se objeví bolest v bederní oblasti, cvik přerušte.`],techniqueNotes:[`Kolena lehce pokrčená.`,`Lokty veďte podél trupu.`]},"towel-row":{name:`Přítah na ručníku`,description:`Přitahování vlastního těla za ručník upevněný na pevné opoře. Posiluje záda a bicepsy bez vybavení.`,steps:[`Ovažte pevný ručník kolem bezpečné opory ve výšce pasu a uchopte oba konce.`,`Zakloňte se na natažených pažích, chodidla blíže k opoře.`,`Přitáhněte hrudník k rukám a veďte lokty dozadu.`,`Pomalu napněte paže a vraťte se do výchozí polohy.`],warnings:[`Ručník upevňujte jen na bezpečnou oporu: stabilní sloup, zábradlí nebo kliku zavřených dveří, které se otevírají směrem od vás.`,`Ověřte, že je ručník pevný a nevyklouzne z rukou.`],techniqueNotes:[`Držte tělo rovně od hlavy po paty.`,`Čím blíže jsou chodidla k opoře, tím je cvik těžší.`]},"inverted-table-row":{name:`Přítah pod stolem`,description:`Horizontální přitahování vleže pod pevným stolem. Posiluje záda, bicepsy a zadní deltové svaly.`,steps:[`Lehněte si na záda pod stůl tak, aby hrudník byl pod hranou desky.`,`Uchopte hranu desky úchopem na šířku ramen.`,`Zatněte břišní svaly a hýždě, přitáhněte hrudník k hraně stolu.`,`Pomalu se spusťte a úplně napněte paže.`],warnings:[`Používejte jen těžký stabilní stůl, který se nepřevrhne a udrží vaši váhu.`,`Držte se hrany desky, ne skla ani složitých prvků.`],techniqueNotes:[`Tělo rovné od ramen po paty, pánev se neprověšuje.`,`Pro usnadnění pokrčte kolena a postavte chodidla na podlahu.`]},"prone-y-t-w-raise":{name:`Zvedání paží Y-T-W vleže`,description:`Zvedání paží ve třech polohách vleže na břiše. Posiluje horní část zad a stabilizátory lopatek.`,steps:[`Lehněte si na břicho, čelo nad podlahou, paže natažené dopředu.`,`Zvedněte paže do tvaru Y, na vteřinu vydržte a spusťte.`,`Rozpažte do tvaru T, zvedněte a spusťte.`,`Pokrčte lokty do tvaru W, stáhněte lopatky, zvedněte a spusťte paže. To je jedno opakování.`],warnings:[`Nezaklánějte hlavu dozadu.`,`Pokud se objeví bolest v ramenou nebo krku, cvik přerušte.`],techniqueNotes:[`Pohyb vychází z lopatek, ne z beder.`,`Palce směřují vzhůru.`]},"reverse-snow-angel":{name:`Obrácený sněhový anděl`,description:`Plynulý pohyb paží od boků k hlavě vleže na břiše. Posiluje horní část zad a zlepšuje pohyblivost ramen.`,steps:[`Lehněte si na břicho, paže podél těla, dlaně k bokům.`,`Zvedněte paže nad podlahu a stáhněte lopatky.`,`Pomalu veďte paže obloukem do stran až k hlavě.`,`Stejnou cestou vraťte paže k bokům, aniž byste se dotkli podlahy.`],warnings:[`Nezaklánějte hlavu dozadu.`,`Pokud se objeví bolest v ramenou nebo krku, cvik přerušte.`],techniqueNotes:[`Paže držte celou dobu mírně nad podlahou.`,`Neprohýbejte bedra, hýždě jsou napnuté.`]},"leg-press":{name:`Leg press`,description:`Tlak nohama na plošinu vsedě. Posiluje čtyřhlavý sval stehenní a hýžďové svaly bez zátěže páteře, vhodné pro začátečníky.`,steps:[`Sedněte si do stroje, přitiskněte bedra k opěradlu, chodidla na plošině na šířku ramen.`,`Uvolněte zarážky a pomalu pokrčte kolena do pohodlné hloubky.`,`Při výdechu napněte nohy, aniž byste kolena úplně zamkli.`,`Po skončení série vraťte zarážky na místo.`],warnings:[`Pokud se objeví bolest v kolenou, cvik přerušte.`],techniqueNotes:[`Bedra se neodlepují od opěradla.`,`Kolena směřují stejným směrem jako špičky.`]},"machine-chest-press":{name:`Tlak na hrudník na stroji`,description:`Tlak za rukojeti od hrudníku vsedě. Bezpečně učí pohyb tlaku a posiluje hrudník, ramena a triceps.`,steps:[`Nastavte sedák tak, aby rukojeti byly ve výšce středu hrudníku.`,`Uchopte rukojeti a přitiskněte lopatky k opěradlu.`,`Při výdechu napněte paže dopředu, aniž byste lokty úplně zamkli.`,`Pomalu vraťte rukojeti a ucítíte protažení hrudníku.`],warnings:[`Pokud se objeví bolest v ramenou, cvik přerušte.`],techniqueNotes:[`Ramena nezvedejte k uším.`]},"machine-shoulder-press":{name:`Tlak nad hlavu na stroji`,description:`Svislý tlak vsedě na stroji. Posiluje ramena a triceps s oporou zad.`,steps:[`Nastavte sedák tak, aby rukojeti byly ve výšce ramen.`,`Přitiskněte záda k opěradlu a uchopte rukojeti.`,`Při výdechu napněte paže vzhůru.`,`Pomalu spusťte rukojeti do úrovně ramen.`],warnings:[`Pokud se objeví bolest v ramenou, cvik přerušte.`],techniqueNotes:[`Neprohýbejte bedra.`]},"seated-cable-row":{name:`Přítah kladky k břichu vsedě`,description:`Horizontální přítah rukojeti kladky. Posiluje záda a zadní deltové svaly, učí stahovat lopatky.`,steps:[`Sedněte si, postavte chodidla na opěrky, uchopte rukojeť s rovnými zády.`,`Přitáhněte rukojeť k břichu a stáhněte lopatky.`,`V koncové poloze na okamžik zastavte.`,`Pomalu vraťte paže dopředu, aniž byste zakulatili záda.`],warnings:[`Pokud se objeví bolest v bederní oblasti, cvik přerušte.`],techniqueNotes:[`Trup je téměř nehybný.`,`Lokty se pohybují podél těla.`]},"lat-pulldown-machine":{name:`Stahování horní kladky`,description:`Stahování široké rukojeti k hrudníku vsedě. Připravuje na shyby a posiluje široký sval zádový.`,steps:[`Zajistěte stehna pod válci, uchopte rukojeť šířeji než ramena.`,`Lehce se zakloňte a stáhněte rukojeť k hornímu okraji hrudníku.`,`Stáhněte lopatky a na okamžik zastavte.`,`Pomalu vraťte rukojeť nahoru.`],warnings:[],techniqueNotes:[`Táhněte lokty, ne zápěstími.`]},"leg-curl-machine":{name:`Zanožování na stroji`,description:`Izolované pokrčování nohou vleže nebo vsedě. Posiluje zadní stranu stehen.`,steps:[`Nastavte válec tak, aby byl nad patami.`,`Při výdechu pokrčte nohy a přitáhněte paty k hýždím.`,`V horní poloze na okamžik zastavte.`,`Pomalu napněte nohy.`],warnings:[`Pokud se objeví bolest v kolenou, cvik přerušte.`],techniqueNotes:[`Pánev se neodlepuje od lavice.`]},"leg-extension-machine":{name:`Předkopávání na stroji`,description:`Izolované natahování nohou vsedě. Posiluje čtyřhlavý sval stehenní.`,steps:[`Nastavte opěradlo a válec nad holeně.`,`Při výdechu napněte nohy.`,`V horní poloze na okamžik zastavte.`,`Pomalu spusťte nohy.`],warnings:[`Pokud se objeví bolest v kolenou, cvik přerušte.`],techniqueNotes:[`Pohyby jsou plynulé, bez škubání.`]},"cable-triceps-pushdown":{name:`Stahování kladky na triceps`,description:`Natahování paží dolů na horní kladce. Izolovaně posiluje triceps.`,steps:[`Postavte se před kladku, uchopte rukojeť, lokty přitisknuté k bokům.`,`Při výdechu napněte paže dolů.`,`Dole na okamžik zastavte.`,`Pomalu vraťte rukojeť do úrovně hrudníku.`],warnings:[],techniqueNotes:[`Lokty se nehýbou.`]},"cable-biceps-curl":{name:`Zdvih na biceps na dolní kladce`,description:`Zdvih paží ve stoje u dolní kladky. Izolovaně posiluje biceps.`,steps:[`Postavte se před dolní kladku, uchopte rukojeť dlaněmi vzhůru.`,`Při výdechu pokrčte paže k ramenům.`,`Nahoře na okamžik zastavte.`,`Pomalu napněte paže.`],warnings:[],techniqueNotes:[`Lokty přitisknuté k bokům, trup nehybný.`]},"cable-face-pull":{name:`Přítah lana k obličeji`,description:`Přítah lanové rukojeti do úrovně obličeje. Posiluje zadní deltové svaly a svaly mezi lopatkami, prospívá držení těla.`,steps:[`Upevněte lano na kladce ve výšce obličeje a ustupte o krok.`,`Přitáhněte lano k obličeji a rozevírejte lokty do stran.`,`Stáhněte lopatky a na okamžik zastavte.`,`Pomalu vraťte paže dopředu.`],warnings:[],techniqueNotes:[`Váha je lehká, pohyb kontrolovaný.`]},"cable-woodchop":{name:`Sekání dřeva na kladce`,description:`Diagonální rotace trupu s rukojetí kladky. Posiluje šikmé břišní svaly a učí přenášet sílu přes střed těla.`,steps:[`Postavte se bokem ke kladce, uchopte rukojeť oběma rukama.`,`Táhněte rukojeť diagonálně dolů a otáčejte trup.`,`Paže držte téměř natažené, otáčejte hrudním košem.`,`Pomalu vraťte rukojeť a opakujte, pak vyměňte stranu.`],warnings:[`Pokud se objeví bolest v bederní oblasti, cvik přerušte.`],techniqueNotes:[`Pohybujte trupem, ne jen pažemi.`]},"barbell-bench-press":{name:`Bench press s velkou činkou`,description:`Klasický tlak velké činky na vodorovné lavici. Základní cvik na hrudník, ramena a triceps.`,steps:[`Lehněte si na lavici, chodidla na podlaze, lopatky stažené, oči pod tyčí.`,`Sundejte činku a spusťte ji doprostřed hrudníku.`,`Při výdechu tlačte činku vzhůru, dokud se paže nenatáhnou.`,`Po skončení série vraťte činku do stojanu.`],warnings:[`V posilovně netlačte činku bez jištění a při bolesti v ramenou cvik přerušte.`],techniqueNotes:[`Ponechte si parťáka na jištění nebo používejte zarážky.`,`Zápěstí nad lokty.`]},"barbell-bent-over-row":{name:`Přítah velké činky v předklonu`,description:`Přítah velké činky k břichu v předklonu. Posiluje celá záda, zadní deltové svaly a biceps.`,steps:[`Postavte se s chodidly na šířku ramen, uchopte tyč úchopem o něco širším než ramena.`,`Předkloňte se s rovnými zády, kolena lehce pokrčená.`,`Přitáhněte činku k dolní části břicha.`,`Pomalu činku spusťte, aniž byste zakulatili záda.`],warnings:[`Pokud se objeví bolest v bederní oblasti, cvik přerušte.`],techniqueNotes:[`Záda rovná po celou dobu pohybu.`]},"barbell-overhead-press":{name:`Tlak s velkou činkou ve stoje`,description:`Tlak velké činky nad hlavu ve stoje. Rozvíjí sílu ramen a horní části zad, vyžaduje stabilní trup.`,steps:[`Vezměte činku do úrovně klíčních kostí úchopem o něco širším než ramena.`,`Zatněte břišní svaly a hýždě, při výdechu tlačte činku vzhůru.`,`Nahoře hlava projde mírně dopředu, činka je nad středem chodidla.`,`Pomalu spusťte činku ke klíčním kostem.`],warnings:[`Pokud se objeví bolest v ramenou nebo bedrech, cvik přerušte.`],techniqueNotes:[`Neprohýbejte bedra.`]},"barbell-romanian-deadlift":{name:`Rumunský mrtvý tah s velkou činkou`,description:`Tah s téměř rovnýma nohama. Posiluje zadní stranu stehen a hýždě, učí pohyb s posunem pánve dozadu.`,steps:[`Postavte se s činkou v rukou, kolena lehce pokrčená.`,`Posouvejte pánev dozadu a veďte činku podél nohou.`,`Spusťte ji pod kolena a udržte rovná záda.`,`Při výdechu se vraťte do výchozí polohy tlakem pánve dopředu.`],warnings:[`Pokud se objeví bolest v bederní oblasti, cvik přerušte.`],techniqueNotes:[`Pohyb vychází z pánve, ne ze zad.`]},"treadmill-incline-walk":{name:`Chůze do kopce na pásu`,description:`Rychlá chůze na běžeckém pásu se sklonem. Bezrázové kardio zatížení pro vytrvalost a nohy.`,steps:[`Nastavte sklon 4–8 % a pohodlnou svižnou chůzi.`,`Držte trup zpříma a neopírejte se o madla.`,`Choďte stabilním tempem po potřebný čas.`,`Na konci snižte rychlost a sklon pro zotavení.`],warnings:[],techniqueNotes:[`Dech zůstává rovnoměrný, můžete mluvit krátkými větami.`]},"easy-run-intervals":{name:`Lehký běh v intervalech`,description:`Střídání klidného běhu a chůze. Rozvíjí vytrvalost srdce a dýchání bez prudké zátěže.`,steps:[`Rozehřejte se minutu svižnou chůzí.`,`Běžte v pohodlném tempu stanovený čas.`,`Přejděte na chůzi pro zotavení.`,`Opakujte střídání podle počtu sérií.`],warnings:[`Pokud se objeví bolest v kotnících nebo kolenou, přestaňte běžet.`],techniqueNotes:[`Tempo umožňuje dýchat nosem nebo mluvit krátkými větami.`]},"sprint-intervals":{name:`Sprinterské úseky`,description:`Krátké úseky plnou rychlostí s plným odpočinkem. Rozvíjejí výkon a rychlostní vytrvalost.`,steps:[`Dobře se rozcvičte a proběhněte několik lehkých zrychlení.`,`Zrychlete na rychlost kolem 90 % maxima.`,`Po úseku se vraťte krokem a plně se zotavte.`,`Opakujte podle počtu sérií.`],warnings:[`Neprovádějte na kluzkém povrchu a při bolesti v kolenou nebo kotnících cvik přerušte.`],techniqueNotes:[`Nakloňte trup dopředu a pracujte pažemi.`]},"brisk-walk-intervals":{name:`Svižná chůze v intervalech`,description:`Střídání svižné a klidné chůze na čerstvém vzduchu. Vhodné pro začátek i zotavení.`,steps:[`Minutu jděte klidně na rozehřátí.`,`Jděte svižně a pohupujte pokrčenými pažemi.`,`Přejděte na klidný krok pro zotavení.`,`Opakujte střídání.`],warnings:[],techniqueNotes:[`Svižný krok: dech je zrychlený, ale stále můžete mluvit.`]},"walking-lunge":{name:`Chodecké výpady`,description:`Výpady s postupem vpřed. Posilují nohy a hýždě a učí rovnováze.`,steps:[`Postavte se zpříma, ruce v bok nebo podél těla.`,`Udělejte široký krok vpřed a klesněte pokrčením obou kolen do 90°.`,`Odrazte se přední nohou a přitáhněte zadní k přednímu kroku.`,`Pokračujte a střídejte nohy.`],warnings:[`Pokud se objeví bolest v kolenou, cvik přerušte.`],techniqueNotes:[`Přední koleno nad kotníkem.`]},"bear-crawl":{name:`Medvědí chůze`,description:`Pohyb na čtyřech opěrných bodech se zvednutými koleny. Posiluje ramena, trup a nohy, rozvíjí koordinaci.`,steps:[`Postavte se na dlaně a chodidla, kolena 5 cm nad zemí.`,`Současně přesouvejte protilehlou paži a nohu dopředu.`,`Držte záda rovně, pánev nízko.`,`Pohybujte se stanovený čas, potom stejně zpět.`],warnings:[`Pokud se objeví bolest v zápěstích, cvik přerušte.`],techniqueNotes:[`Pohyby jsou pomalé a kontrolované.`]},"broad-jump":{name:`Skok daleký z místa`,description:`Výbušný skok vpřed snožmo. Rozvíjí výkon nohou a koordinaci.`,steps:[`Postavte se s chodidly na šířku ramen, paže vzad.`,`Odrazte se s švihem paží vpřed a skočte co nejdál.`,`Dopadněte měkce na pokrčená kolena.`,`Zastavte se, obnovte rovnováhu a opakujte.`],warnings:[`Neprovádějte na kluzkém povrchu a při bolesti v kolenou cvik přerušte.`],techniqueNotes:[`Měkký dopad na celé chodidlo.`]},"skater-jumps":{name:`Bruslařské skoky`,description:`Boční skoky z nohy na nohu. Trénují rovnováhu, nohy a vytrvalost.`,steps:[`Postavte se na jednu nohu, druhou zanožte.`,`Skočte do strany na druhou nohu a švihněte pažemi.`,`Na okamžik se zastavte a udržte rovnováhu.`,`Skočte zpět a pokračujte stanovený čas.`],warnings:[`Pokud se objeví bolest v kolenou nebo kotnících, cvik přerušte.`],techniqueNotes:[`Měkký dopad, koleno za špičkou.`]},"shuttle-run":{name:`Člunkový běh`,description:`Běh mezi dvěma body se změnou směru. Rozvíjí rychlost reakce a vytrvalost.`,steps:[`Označte dva body ve vzdálenosti 3 m od sebe.`,`Proběhněte ke druhému bodu a dotkněte se země rukou.`,`Rychle se otočte a běžte zpět.`,`Opakujte stanovený čas.`],warnings:[`Neprovádějte na kluzkém povrchu.`],techniqueNotes:[`Otáčejte se s pokrčenými koleny, noha se nezanáší do strany.`]},"stair-climb":{name:`Výstup po schodech`,description:`Rychlý výstup po schodech nebo strmém svahu. Kardio a posílení nohou a hýždí.`,steps:[`Postavte se na začátek schodů nebo svahu.`,`Vystupujte rychlým krokem a na schod stavte celé chodidlo.`,`Stoupejte stanovený čas, pak sestupujte pomalu.`,`Opakujte podle počtu sérií.`],warnings:[`Pokud se objeví bolest v kolenou, cvik přerušte.`],techniqueNotes:[`Sestup klidný, v případě potřeby se držte zábradlí.`]},"park-bench-step-up":{name:`Výstup na lavičku v parku`,description:`Výstup na stabilní lavičku na jedné noze. Posiluje čtyřhlavý sval stehenní a hýždě.`,steps:[`Ověřte, že je lavička stabilní, a postavte se před ni.`,`Postavte jedno chodidlo na lavičku a vystupte napnutím nohy.`,`Sestupte pomalu a kontrolovaně.`,`Dokončete sérii a vyměňte nohu.`],warnings:[`Pokud se objeví bolest v kolenou, cvik přerušte.`],techniqueNotes:[`Tlačte nohou, která stojí na lavičce, neodrážejte se od země.`]},"park-bench-incline-push-up":{name:`Kliky o lavičku`,description:`Kliky s oporou rukou o lavičku. Usnadněná varianta pro hrudník, ramena a triceps.`,steps:[`Položte dlaně na okraj stabilní lavičky, tělo v jedné linii.`,`Pokrčte lokty a spusťte hrudník k lavičce.`,`Při výdechu se odrazte, až se paže napnou.`,`Držte trup napnutý po celou dobu pohybu.`],warnings:[`Pokud se objeví bolest v zápěstích, cvik přerušte.`],techniqueNotes:[`Lokty v úhlu přibližně 45° od trupu.`]},"australian-pull-up":{name:`Australský shyb`,description:`Přitahování těla k nízké tyči vleže pod ní. Posiluje záda a biceps, je lehčí než klasické shyby.`,steps:[`Postavte se pod nízkou pevnou tyč a uchopte ji úchopem šířeji než ramena.`,`Natáhněte tělo do přímé linie, paty na zemi.`,`Přitáhněte hrudník k tyči a stáhněte lopatky.`,`Pomalu se spusťte do téměř natažených paží.`],warnings:[`Ujistěte se, že je tyč pevná, a při bolesti v ramenou cvik přerušte.`],techniqueNotes:[`Tělo zůstává rovné, pánev se neprověšuje.`]},"outdoor-plank-shoulder-taps":{name:`Prkno s dotyky ramen`,description:`Prkno se střídavými dotyky ramene. Posiluje střed těla a stabilitu ramen.`,steps:[`Zaujměte polohu vysokého prkna, chodidla o něco šířeji než ramena.`,`Dotkněte se pravou rukou levého ramene a nehoupejte pánví.`,`Vraťte ruku a dotkněte se druhou.`,`Střídejte stanovený čas.`],warnings:[`Pokud se objeví bolest v zápěstích, cvik přerušte.`],techniqueNotes:[`Pánev se téměř nehýbe.`]}};export{t as burpee,s as default,n as plank,a as superman};